/* REAL-MATH AR v3 — interfaz sin dependencias de framework. */
'use strict';
const $=id=>document.getElementById(id);
let user=null, currentRoute='dashboard', routeArgs={}, catalogCache=[], courseCache=null, questionCache=null, activeQuiz=null, examInterval=null;
const subjects={geometria:'Geometría',algebra:'Álgebra',calculo:'Cálculo',otras:'Otras matemáticas'};
const icons={geometria:'△',algebra:'∑',calculo:'∫',otras:'◇'};
const models={none:'Sin modelo 3D',pitagoras:'Triángulo de Pitágoras',identidad_algebraica:'Identidad (a+b)²',...Object.fromEntries([-2,-1,0,1,2].map(k=>['calculo_'+k,'Superficie 3D (a = '+k+')']))};
const studyQuestions=[
 ['En un triángulo rectángulo con catetos 3 y 4, ¿cuánto vale la hipotenusa?',['6','5','7']],
 ['¿Cuál es la expansión correcta de (a+b)²?',['a²+b²','a²+ab+b²','a²+2ab+b²']],
 ['¿Cómo es la concavidad de f(x)=a·x² si a es negativo?',['Hacia abajo','Hacia arriba','No existe']],
 ['Pasar de (a+b)² a (a+b)(a+b) usa...',['Distributividad','Definición de potencia al cuadrado','Conmutatividad']],
 ['Si z=x²+y², ¿cuánto es z en el origen (0,0)?',['1','2','0']],
 ['Los cuadrados de los catetos miden 9 y 16 de área. El de la hipotenusa mide...',['7','25','9']]
];
const perceptionQuestions=['Los modelos 3D facilitaron mi comprensión de los conceptos.','Pude seguir las justificaciones de las demostraciones.','Las actividades y la retroalimentación me ayudaron a identificar errores.','Utilizaría recursos de este tipo para reforzar matemáticas.'];
function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function br(x){return esc(x).replace(/\n/g,'<br>');}
function txt(x){return esc(x||'');}
function toast(message,error=false){const t=$('toast');t.textContent=message;t.className='toast visible'+(error?' error':'');clearTimeout(toast.t);toast.t=setTimeout(()=>t.className='toast',4500);}
function btn(label,action,attrs='',variant='secondary'){return `<button type="button" class="btn ${variant}" data-action="${action}" ${attrs}>${label}</button>`;}
async function api(path,method='GET',payload){const opts={method,credentials:'same-origin',headers:{}};if(method!=='GET'){opts.headers['X-CSRF-Token']=user?.csrf||'';opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(payload??{});}let response;try{response=await fetch(path,opts);}catch(e){throw Error('No hay conexión con el servidor. Abre la aplicación desde http://127.0.0.1:8000.');}
 const j=await response.json().catch(()=>({}));if(!response.ok){let message=Array.isArray(j.detail)?j.detail.map(d=>d.msg).join(', '):String(j.detail||j.message||'Error inesperado');if(response.status===401 && user && !['/api/profile/email','/api/profile/password','/api/profile'].includes(path)){user=null;showAuth('login');}throw Error(message);}return j;}
function formatDate(unix){return unix?new Date(unix*1000).toLocaleString('es-CO'):'—'}
function trim(s,n=150){return s?.length>n?s.slice(0,n)+'…':(s||'');}
function clearTimer(){if(examInterval){clearInterval(examInterval);examInterval=null;}}
function authText(mode){return {
  login:['Accede a tu cuenta','Tu curso y progreso siempre estarán disponibles.'],student:['Crea tu cuenta de estudiante','Explora recursos, presenta exámenes y guarda tus avances.'],teacher:['Registro de profesor','Crea tu cuenta docente con tu nombre, correo y contraseña.'],forgot:['Recupera tu contraseña','Te enviaremos instrucciones al correo registrado.'],reset:['Establece una nueva contraseña','El enlace solo se puede usar una vez.']
}[mode]||[];}
function field(label,name,type='text',value='',required=true,extra=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></label>`;}
function showAuth(mode='login'){
 clearTimer();$('platform').classList.add('hidden');$('authView').classList.remove('hidden');
 const [title,sub]=authText(mode);$('authTitle').textContent=title;$('authSubtitle').textContent=sub;
 document.querySelectorAll('[data-auth]').forEach(b=>b.classList.toggle('active',b.dataset.auth===mode));
 const area=$('authFormArea');let html='';
 if(mode==='login')html=`<form id="authForm" data-mode="login">${field('Correo electrónico','email','email','',true,'autocomplete="email"')}${field('Contraseña','password','password','',true,'autocomplete="current-password"')}<button class="btn primary wide" type="submit">Entrar a mi cuenta →</button></form>`;
 if(mode==='student'||mode==='teacher')html=`<form id="authForm" data-mode="${mode}">${field('Nombre completo','name','text','',true,'minlength="2" maxlength="90" autocomplete="name"')}${field('Correo electrónico','email','email','',true,'autocomplete="email"')}${field('Contraseña segura','password','password','',true,'minlength="10" maxlength="128" autocomplete="new-password"')}${field('Confirmar contraseña','confirm','password','',true,'minlength="10" maxlength="128" autocomplete="new-password"')}<p class="mini-note">Usa al menos 10 caracteres, con letras y números.</p><button class="btn primary wide" type="submit">Crear cuenta ${mode==='teacher'?'de profesor':'de estudiante'}</button></form>`;
 if(mode==='forgot')html=`<form id="authForm" data-mode="forgot">${field('Correo registrado','email','email')}<button class="btn primary wide" type="submit">Solicitar enlace de recuperación</button>${btn('Volver al inicio','back-login','','outline')}</form>`;
 if(mode==='reset')html=`<form id="authForm" data-mode="reset">${field('Nueva contraseña','password','password','',true,'minlength="10"')}${field('Confirmar contraseña','confirm','password','',true,'minlength="10"')}<button class="btn primary wide" type="submit">Guardar nueva contraseña</button></form>`;
 area.innerHTML=html;
}
async function handleAuth(form){const f=new FormData(form),mode=form.dataset.mode,body=Object.fromEntries(f.entries());
 try{
 if(mode==='login'){const data=await api('/api/login','POST',{email:body.email,password:body.password});onLogin(data);return;}
 if(mode==='student'||mode==='teacher'){
   if(body.password!==body.confirm)throw Error('Las contraseñas no coinciden.');
   const endpoint=mode==='teacher'?'/api/register-teacher':'/api/register';
   const payload = {
    name: body.name,
    email: body.email,
    password: body.password
};
   const data=await api(endpoint,'POST',payload);onLogin(data);return;
 }
 if(mode==='forgot'){await api('/api/forgot','POST',{email:body.email});toast('Si el correo está registrado, se enviarán las instrucciones. En modo local consulta data/dev_mail.log.');showAuth('login');return;}
 if(mode==='reset'){if(body.password!==body.confirm)throw Error('Las contraseñas no coinciden.');const token=new URL(location.href).searchParams.get('reset_token');await api('/api/reset-password','POST',{token,password:body.password});history.replaceState(null,'',location.pathname);toast('Contraseña cambiada. Inicia sesión.');showAuth('login');}
 }catch(e){toast(e.message,true);}}

function onLogin(data) {
    user = data;

    $('authView').classList.add('hidden');
    $('platform').classList.remove('hidden');

    $('userName').textContent = data.name;
    $('userRole').textContent =
        data.role === 'teacher' ? 'Profesor/a' : 'Estudiante';

    $('avatar').textContent =
        data.name.charAt(0).toUpperCase();

    $('rolePill').textContent =
        data.role === 'teacher'
            ? 'Espacio docente'
            : 'Espacio estudiante';

    renderNav();

    // Recuperar la lección desde la que se abrió la RA.
    const params = new URLSearchParams(window.location.search);
    const curso = params.get('course');
    const leccion = params.get('lesson');

    if (/^[1-9]\d*$/.test(curso || '') &&
        /^[1-9]\d*$/.test(leccion || '')) {

        history.replaceState(null, '', location.pathname);

        go('lesson', {
            id: Number(leccion),
            course: Number(curso)
        });

    } else {
        go('dashboard');
    }
}

function renderNav(){const links=user.role==='teacher'?[['dashboard','⌂','Inicio'],['courses','▣','Mis cursos'],['teacher-report','▤','Resultados'],['settings','⚙','Configuración']]:[['dashboard','⌂','Inicio'],['catalog','▣','Explorar cursos'],['my-courses','◫','Mis cursos'],['evaluations','▥','Mis evaluaciones'],['progress','◉','Mi progreso'],['research','✦','Investigación'],['settings','⚙','Configuración']];$('navigation').innerHTML=links.map(([id,icon,title])=>`<button type="button" class="nav-item ${currentRoute===id?'active':''}" data-route="${id}"><span class="nav-icon">${icon}</span>${title}</button>`).join('');}
function setPage(title,html){$('pageTitle').textContent=title;$('page').innerHTML=html;document.querySelectorAll('[data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route===currentRoute));$('page').focus({preventScroll:true});}
function pageHeader(title,description='',actions=''){return `<div class="page-head"><div><div class="overline">REAL-MATH AR · ${user.role==='teacher'?'DOCENCIA':'APRENDIZAJE'}</div><h1>${title}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>`;}
function errorPage(e){setPage('Ocurrió un error',`<div class="empty"><div class="empty-icon">!</div><h3>No se pudo completar esta acción</h3><p>${esc(e.message)}</p>${btn('Volver al inicio','home','','primary')}</div>`);}
async function go(route,args={}){if(!user){showAuth('login');return;}clearTimer();currentRoute=route;routeArgs=args;renderNav();window.scrollTo({top:0,behavior:'instant'});document.querySelector('.sidebar').classList.remove('open');setPage('Cargando...',`<div class="empty">Cargando contenido…</div>`);
 try{switch(route){
 case 'dashboard':await renderDashboard();break;case 'catalog':case 'my-courses':case 'courses':await renderCatalog(route);break;case 'course':await renderCourse(args.id);break;case 'lesson':await renderLesson(args.id,args.course);break;case 'take':await renderQuizAttempt(args.id);break;case 'evaluations':await renderEvaluations();break;case 'progress':await renderProgress();break;case 'research':await renderResearch();break;case 'settings':renderSettings();break;case 'new-course':case 'edit-course':await renderCourseForm(args.id);break;case 'new-lesson':case 'edit-lesson':await renderLessonForm(args.course,args.lesson);break;case 'new-quiz':case 'edit-quiz':await renderQuizForm(args.course,args.quiz);break;case 'questions':await renderQuestions(args.quiz,args.course);break;case 'question-form':await renderQuestionForm(args.quiz,args.course,args.question);break;case 'teacher-report':await renderTeacherReports(args.id);break;default:await renderDashboard();}
 }catch(e){errorPage(e);}}
function courseCard(c){const staff=user.role==='teacher',enrolled=!!c.enrolled;
 return `<article class="card course-card" data-subject="${esc(c.subject)}"><div class="course-icon">${icons[c.subject]||'◇'}</div><div class="pill-row"><span class="tag">${esc(subjects[c.subject]||c.subject)}</span><span class="tag ${c.published?'success':'warn'}">${c.published?'Publicado':'Borrador'}</span></div><h3 style="margin-top:13px">${esc(c.title)}</h3><p class="mini-note"><b>Profesor responsable:</b> ${esc(c.teacher_name||'Sin profesor asignado')}</p><p>${esc(trim(c.description,165))}</p><div class="course-footer"><span class="mini-note">${c.lesson_count||0} lecciones ${staff?'· '+(c.students||0)+' estudiantes':''}</span>${staff||enrolled?btn('Abrir →','course',`data-id="${c.id}"`,'secondary'):btn('Inscribirme','enroll-public',`data-id="${c.id}"`,'primary')}</div></article>`;}
async function renderDashboard(){if(user.role==='teacher'){
  const [courses,tc]=await Promise.all([api('/api/catalog'),api('/api/teacher/join-code')]);setPage('Inicio',`<div class="hero"><div><div class="overline">PANEL DEL PROFESOR</div><h1>¡Hola, ${esc(user.name.split(' ')[0])}!</h1><p>Organiza tus materias, publica explicaciones, acompaña a tus estudiantes y evalúa sus conocimientos.</p>${btn('+ Crear un curso','new-course','','primary')}</div><div class="hero-symbol">◈</div></div><div class="card spaced"><h3>Código de inscripción de profesor</h3><p class="mini-note">Comparte este código con tus estudiantes para que puedan inscribirse en tus cursos publicados.</p><div class="pill-row"><span class="tag success" style="font-size:18px;letter-spacing:2px">${esc(tc.code)}</span>${btn('Copiar código','copy-teacher-code',`data-code="${esc(tc.code)}"`,'outline')}</div><p class="mini-note">Para modificarlo, abre uno de tus cursos y selecciona «Editar curso».</p></div><div class="section-title"><div><h2>Tus cursos</h2><p>Tu contenido es independiente del de otros profesores.</p></div>${btn('Ver todos','courses','','outline')}</div>${courses.length?`<div class="grid">${courses.slice(0,6).map(courseCard).join('')}</div>`:empty('Todavía no tienes cursos','Crea uno para empezar a publicar contenido y evaluaciones.')}`);return;}
 const [stats,courses]=await Promise.all([api('/api/student/overview'),api('/api/catalog')]);
 setPage('Inicio',`<div class="hero"><div><div class="overline">TU LABORATORIO MATEMÁTICO</div><h1>¡Hola, ${esc(user.name.split(' ')[0])}! Sigue aprendiendo.</h1><p>Explora teoremas y demostraciones, observa modelos aumentados y mide tu aprendizaje.</p>${btn('Explorar cursos →','catalog','','primary')}</div><div class="hero-symbol">△</div></div><div class="grid four spaced">${statCard('Cursos inscritos',stats.courses,'▣')}${statCard('Lecciones completadas',stats.lessons_completed,'✔')}${statCard('Evaluaciones realizadas',stats.exams_taken,'▤')}${statCard('Promedio de respuestas',stats.average_percent+'%','◉')}</div><div class="section-title"><div><h2>Contenidos disponibles</h2><p>Tres áreas de matemáticas universitarias y cursos creados por profesores.</p></div>${btn('Ver catálogo','catalog','','outline')}</div><div class="grid">${courses.slice(0,6).map(courseCard).join('')}</div>`);
}
function statCard(label,value,icon){return `<div class="stat"><span class="stat-icon">${icon}</span><small>${esc(label)}</small><strong>${esc(value)}</strong></div>`;}
function empty(title,sub){return `<div class="empty"><div class="empty-icon">◇</div><h3>${esc(title)}</h3><p>${esc(sub)}</p></div>`;}
async function renderCatalog(type){const list=await api('/api/catalog');catalogCache=list;let courses=type==='my-courses'?list.filter(x=>x.enrolled):list;
 const teacher=user.role==='teacher',title=teacher?'Mis cursos':type==='my-courses'?'Mis cursos inscritos':'Catálogo de aprendizaje';
 setPage(title,pageHeader(title,teacher?'Crea contenidos por materia, clases y evaluaciones.':'Encuentra una asignatura y empieza a aprender.',teacher?btn('+ Nuevo curso','new-course','','primary'):(type==='catalog'?btn('Inscribirme con código','join-code','','outline'):''))+
 (courses.length?`<div class="grid">${courses.map(courseCard).join('')}</div>`:empty('No hay cursos todavía','Explora el catálogo o crea tu primer curso.')));
}
async function renderCourse(id){const c=await api('/api/courses/'+id);courseCache=c;const teacher=user.role==='teacher';const tc=teacher?await api('/api/teacher/join-code'):null;
 const lessons=c.lessons.map(l=>`<div class="list-row"><div><h3>${l.completed?'✅ ':''}${esc(l.title)} ${l.ar_model!=='none'?'<span class="tag">3D / RA</span>':''}</h3><p>${l.published?'Lección disponible':'Lección oculta'} · ${l.body.length} caracteres</p></div><div class="actions">${teacher?`${btn('Editar','edit-lesson',`data-course="${id}" data-lesson="${l.id}"`,'outline')}${btn('Eliminar','delete-lesson',`data-id="${l.id}" data-course="${id}"`,'danger')}`:btn('Estudiar →','lesson',`data-id="${l.id}" data-course="${id}"`,'secondary')}</div></div>`).join('');
 const exams=c.quizzes.map(q=>`<div class="list-row"><div><h3>${q.kind==='exam'?'▥':'✎'} ${esc(q.title)} <span class="tag ${q.kind==='exam'?'warn':''}">${q.kind==='exam'?'Examen':'Práctica'}</span></h3><p>${q.question_count} preguntas · ${q.time_limit?`${q.time_limit} minutos`:'Sin límite de tiempo'} · ${q.max_attempts} intentos · ${q.published?'Publicado':'Borrador'}</p></div><div class="actions">${teacher?`${btn('Preguntas','questions',`data-quiz="${q.id}" data-course="${id}"`,'secondary')}${btn('Editar','edit-quiz',`data-course="${id}" data-quiz="${q.id}"`,'outline')}${btn('Eliminar','delete-quiz',`data-quiz="${q.id}" data-course="${id}"`,'danger')}`:btn('Responder →','take',`data-id="${q.id}"`,'primary')}</div></div>`).join('');
 const actions=teacher?`${btn('Editar curso','edit-course',`data-id="${id}"`,'outline')}${btn('Resultados','teacher-report',`data-id="${id}"`,'secondary')}${btn('Eliminar curso','delete-course',`data-id="${id}"`,'danger')}`:btn('Salir del curso','unenroll',`data-id="${id}"`,'outline');
 const teacherInfo=teacher?`<div class="card" style="margin-bottom:18px"><b>Acceso del curso:</b> ${c.access_code?`<span class="tag warn">Código privado: ${esc(c.access_code)}</span>`:'<span class="tag success">Inscripción pública</span>'} · <span class="tag ${c.published?'success':'warn'}">${c.published?'Publicado':'Sin publicar'}</span><p class="mini-note" style="margin:8px 0 0"><b>Código del profesor:</b> <strong>${esc(tc.code)}</strong> · ${btn('Copiar código','copy-teacher-code',`data-code="${esc(tc.code)}"`,'outline')}</p><p class="mini-note">Este código permite inscribirse a los cursos publicados de tu cuenta; el código privado del curso, si existe, funciona solamente para esa asignatura.</p></div>`:'';
 setPage(c.title,`${btn('← Volver a cursos','back-courses','','outline')}${pageHeader(esc(c.title),esc(c.description),actions)}<p class="mini-note" style="margin-bottom:14px"><b>Profesor responsable:</b> ${esc(c.teacher_name||'Sin profesor asignado')}</p>${teacherInfo}<div class="section-title"><div><h2>Lecciones y recursos 3D</h2><p>Teoría, demostraciones y exploración visual.</p></div>${teacher?btn('+ Añadir lección','new-lesson',`data-course="${id}"`,'primary'):''}</div><div class="list">${lessons||empty('Sin lecciones','Esta asignatura aún no tiene contenidos publicados.')}</div><div class="section-title"><div><h2>Actividades y exámenes</h2><p>Preguntas calificadas por el servidor y resultados guardados en tu cuenta.</p></div>${teacher?btn('+ Crear evaluación','new-quiz',`data-course="${id}"`,'primary'):''}</div><div class="list">${exams||empty('Sin evaluaciones','Todavía no hay preguntas para este curso.')}</div>`);
}
function modelHtml(model,moreControls=''){if(!model||model==='none')return `<div class="hint">Esta lección es de lectura y práctica. El profesor puede incorporar un modelo de la biblioteca RA cuando sea pertinente.</div>`;
 const filename=model+'.glb',extra=model.startsWith('calculo_')?`<div class="viewer-controls"><label for="surfaceParam"><b>Coeficiente a:</b></label><input id="surfaceParam" type="range" min="-2" max="2" step="1" value="${model.split('_')[1]}"/><strong id="surfaceValue">${model.split('_')[1]}</strong></div><p class="mini-note">La superficie representa z = a(x²+y²). El archivo 3D cambia entre cinco valores discretos.</p><canvas id="miniPlot" width="680" height="260" class="chart"></canvas>`:'';
 return `<div class="model-area"><model-viewer id="arViewer" src="/assets/${esc(filename)}" alt="Modelo matemático: ${esc(models[model]||model)}" camera-controls auto-rotate shadow-intensity=".65" exposure="1.15" ar ar-modes="webxr scene-viewer quick-look" environment-image="neutral" touch-action="pan-y"><button type="button" class="ar-button" slot="ar-button">📱 Ver en mi espacio (RA móvil)</button></model-viewer></div>${extra}${moreControls}<div class="viewer-controls ra-options"><a class="btn primary" href="/ar?model=${encodeURIComponent(model)}&course=${encodeURIComponent(routeArgs.course||'')}&lesson=${encodeURIComponent(routeArgs.id||'')}">📷 Activar RA con la cámara del portátil ↗</a><a class="btn outline" href="/marcador" target="_blank" rel="noopener noreferrer">▣ Ver e imprimir marcador Hiro ↗</a></div><div class="hint">En el computador: pulsa «Activar RA», permite acceder a la cámara y muestra el marcador Hiro delante de la webcam. Para visualizar sin cámara, utiliza el modelo 3D anterior.</div><div class="warn-note">El modo RA con la cámara del portátil utiliza WebAR (AR.js + A-Frame) y un marcador impreso. Requiere conexión a Internet para cargar las bibliotecas. El uso por HTTPS o 127.0.0.1 permite solicitar permiso para la cámara. La detección en tu webcam aún debe comprobarse físicamente.</div>`;
}
async function renderLesson(id,courseId){algStepIndex=0;const c=await api('/api/courses/'+courseId),l=c.lessons.find(x=>x.id===Number(id));if(!l)throw Error('Lección no disponible.');
 const isTeacher=user.role==='teacher';let extras='';
 if(l.ar_model==='pitagoras')extras=`<div class="hint"><b>Exploración de Pitágoras:</b> identifica los catetos y la hipotenusa; explica por qué las áreas de los cuadrados pequeños suman la del mayor. Comprueba el ejemplo 3² + 4² = 5².</div>`;
 if(l.ar_model==='identidad_algebraica')extras=`<div class="hint"><b>Demostración guiada:</b> <span id="algStep">(a+b)²=(a+b)(a+b): definición de potencia.</span><div class="viewer-controls">${btn('Paso anterior','alg-prev','','outline')}${btn('Siguiente paso','alg-next','','secondary')}</div></div>`;
 setPage(l.title,`${btn('← Volver al curso','course',`data-id="${courseId}"`,'outline')}${pageHeader(esc(l.title),`${esc(subjects[c.subject])} · ${esc(c.title)}`,isTeacher?btn('Editar esta lección','edit-lesson',`data-course="${courseId}" data-lesson="${id}"`,'secondary'):'')}<div class="content-columns"><div><div class="card"><h3>Explicación y fundamentos</h3><div class="text-block">${br(l.body)}</div>${l.support_url?`<p class="spaced"><a class="inline-link" href="${esc(l.support_url)}" target="_blank" rel="noopener noreferrer">Consultar material complementario ↗</a></p>`:''}<hr class="divider">${isTeacher?'<p class="mini-note">Vista de profesor: así se presenta tu contenido.</p>':l.completed?'<span class="tag success">✔ Ya completaste esta lección</span>':btn('✓ Marcar lección como completada','complete-lesson',`data-id="${id}" data-course="${courseId}"`,'primary')}</div></div><div class="card"><h3>Laboratorio visual y Realidad Aumentada</h3>${modelHtml(l.ar_model)}${extras}</div></div>`);
 if(l.ar_model.startsWith('calculo_'))initPlot();
}
let algStepIndex=0;
const algSteps=['(a+b)²=(a+b)(a+b). Definición del cuadrado.','(a+b)(a+b)=a²+ab+ba+b². Propiedad distributiva.','a²+ab+ba+b²=a²+2ab+b². Conmutatividad y suma de términos semejantes.','Conclusión: (a+b)²=a²+2ab+b². La figura muestra las cuatro áreas.'];
function drawPlot(a){const cv=$('miniPlot');if(!cv)return;const ctx=cv.getContext('2d');if(!ctx)return;const w=cv.width,h=cv.height;ctx.fillStyle='#101b35';ctx.fillRect(0,0,w,h);ctx.lineWidth=1;ctx.strokeStyle='#ffffff18';for(let x=0;x<w;x+=34){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}for(let y=0;y<h;y+=34){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}ctx.strokeStyle='#ffffffa9';ctx.beginPath();ctx.moveTo(0,h*.72);ctx.lineTo(w,h*.72);ctx.moveTo(w/2,0);ctx.lineTo(w/2,h);ctx.stroke();ctx.strokeStyle='#40d5e1';ctx.lineWidth=4;ctx.beginPath();let first=true;for(let x=-4;x<=4;x+=.04){const xx=w/2+x*60,yy=h*.72-a*x*x*21;if(yy< -200||yy>h+200){first=true;continue;}if(first){ctx.moveTo(xx,yy);first=false;}else ctx.lineTo(xx,yy);}ctx.stroke();}
function initPlot(){const slider=$('surfaceParam');if(slider){drawPlot(Number(slider.value));slider.addEventListener('input',()=>{const a=Number(slider.value);$('surfaceValue').textContent=a;$('arViewer').src='/assets/calculo_'+a+'.glb';drawPlot(a);});}}
async function renderQuizAttempt(quizId){if(user.role!=='student')throw Error('Los exámenes están disponibles para estudiantes.');const q=await api('/api/quizzes/'+quizId+'/start','POST',{});activeQuiz=q;
 const cards=q.questions.map((it,i)=>`<fieldset class="question-card"><legend><b>${i+1}. ${esc(it.prompt)}</b></legend>${it.options.map((opt,j)=>`<label class="answer-choice"><input type="radio" name="q${it.id}" value="${j}" required> <span>${String.fromCharCode(65+j)}. ${esc(opt)}</span></label>`).join('')}</fieldset>`).join('');
 setPage('Evaluación',`${pageHeader(esc(q.title),`${q.kind==='exam'?'Examen':'Práctica'} · ${q.questions.length} preguntas · Las respuestas se califican en el servidor.`)}<div class="content-columns"><div class="card"><form id="quizAnswerForm" data-attempt="${q.attempt_id}">${cards}<button class="btn primary" type="submit">Entregar respuestas y ver resultados</button></form></div><div class="card"><h3>Instrucciones</h3><p>${esc(q.instructions)}</p><div class="hint">Las respuestas correctas no se muestran antes del envío. Tu intento se guarda individualmente.</div>${q.remaining_seconds===null?'<p><span class="tag success">Sin límite de tiempo</span></p>':`<p class="quiz-timer" id="examClock">Tiempo restante: ${Math.floor(q.remaining_seconds/60)}:${String(q.remaining_seconds%60).padStart(2,'0')}</p>`}${btn('Volver al curso','back-courses','','outline')}</div></div>`);
 if(q.remaining_seconds!==null){const end=Date.now()+q.remaining_seconds*1000;examInterval=setInterval(()=>{const seconds=Math.max(0,Math.ceil((end-Date.now())/1000)),clock=$('examClock');if(clock)clock.textContent=`Tiempo restante: ${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;if(seconds===0)clearTimer();},1000);}
}
async function handleQuizSubmit(form){const answers={};for(const [key,value] of new FormData(form))answers[key.slice(1)]=Number(value);try{const res=await api('/api/attempts/'+form.dataset.attempt+'/submit','POST',{choices:answers});clearTimer();activeQuiz=null;renderQuizResult(res);}catch(e){toast(e.message,true);}}
function renderQuizResult(res){setPage('Resultado de la evaluación',`${pageHeader('Resultado del intento','Revisa tu retroalimentación y vuelve a practicar los contenidos relacionados.')}<div class="grid two spaced">${statCard('Puntaje',`${res.score} / ${res.total}`,'▥')}${statCard('Porcentaje',`${res.total?Math.round(100*res.score/res.total):0}%`,'◉')}</div>${res.expired?'<div class="warn-note">El tiempo de tu examen terminó antes de que se recibieran las respuestas. Este intento se registra con cero puntos.</div>':''}<div class="list">${res.details.map((q,i)=>`<div class="card"><h3>${i+1}. ${esc(q.prompt)}</h3><div class="result ${q.correct?'good':'bad'}">${q.correct?'✓ Respuesta correcta':'✗ Respuesta incorrecta o sin responder'} · Opción correcta: ${String.fromCharCode(65+q.correct_index)}</div><p style="margin:14px 0 0">${esc(q.explanation)}</p></div>`).join('')}</div><div class="actions spaced">${btn('Ver evaluaciones','evaluations','','primary')}${btn('Mis cursos','my-courses','','outline')}</div>`);}
async function renderEvaluations(){const attempts=await api('/api/attempts');setPage('Mis evaluaciones',`${pageHeader('Historial de evaluaciones','Los intentos y calificaciones pertenecen exclusivamente a tu cuenta.')}${attempts.length?`<div class="table-wrap card"><table><thead><tr><th>Curso</th><th>Evaluación</th><th>Fecha</th><th>Resultado</th><th>Estado</th></tr></thead><tbody>${attempts.map(a=>`<tr><td>${esc(a.course_title)}</td><td>${esc(a.quiz_title)}</td><td>${formatDate(a.started_at)}</td><td>${a.submitted_at?`${a.score}/${a.total}`:'—'}</td><td><span class="tag ${a.submitted_at?'success':'warn'}">${a.submitted_at?'Enviado':'En curso'}</span></td></tr>`).join('')}</tbody></table></div>`:empty('Todavía no has presentado evaluaciones','Inscríbete en una materia y realiza una práctica o examen.')}`);}
async function renderProgress(){const [s,a,c,perCourse]=await Promise.all([api('/api/student/overview'),api('/api/attempts'),api('/api/catalog'),api('/api/student/progress-courses')]);const enrolled=c.filter(x=>x.enrolled);const pct=s.lessons_total?Math.round(s.lessons_completed*100/s.lessons_total):0;
 setPage('Mi progreso',`${pageHeader('Tu progreso académico','Lecciones, exámenes y avance medible por estudiante.')}<div class="grid four">${statCard('Materias cursadas',s.courses,'▣')}${statCard('Lecciones completadas',s.lessons_completed+'/'+s.lessons_total,'✓')}${statCard('Intentos de examen',s.exams_taken,'▤')}${statCard('Promedio de aciertos',s.average_percent+'%','◉')}</div><div class="card spaced"><div class="bar-row"><h3>Avance de lecciones</h3><strong>${pct}%</strong></div><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div><p class="mini-note">Se contabilizan las lecciones publicadas de los cursos donde estés inscrito.</p></div><div class="section-title"><h2>Progreso por asignatura</h2></div>${perCourse.length?`<div class="list">${perCourse.map(x=>{const rate=x.total_lessons?Math.round(100*x.completed_lessons/x.total_lessons):0;return `<div class="card"><div class="bar-row"><div><h3>${esc(x.title)}</h3><p class="mini-note">${x.completed_lessons}/${x.total_lessons} lecciones · ${x.exam_attempts} intentos · promedio ${x.average_percent??0}%</p></div><strong>${rate}%</strong></div><div class="progress-track"><div class="progress-fill" style="width:${rate}%"></div></div>${btn('Continuar','course',`data-id="${x.id}"`,'outline')}</div>`;}).join('')}</div>`:empty('Sin asignaturas inscritas','Ve al catálogo para comenzar.')}<div class="section-title"><h2>Evaluaciones recientes</h2></div>${a.filter(x=>x.submitted_at).length?`<div class="list">${a.filter(x=>x.submitted_at).slice(0,6).map(x=>`<div class="list-row"><div><h3>${esc(x.quiz_title)}</h3><p>${esc(x.course_title)} · ${formatDate(x.submitted_at)}</p></div><b>${x.score}/${x.total} puntos</b></div>`).join('')}</div>`:empty('No hay resultados todavía','Completa una práctica para ver tus resultados.')}`);
}
function selectField(label,name,options,value=''){return `<label class="field"><span>${label}</span><select name="${name}">${options.map(([key,title])=>`<option value="${esc(key)}" ${String(key)===String(value)?'selected':''}>${esc(title)}</option>`).join('')}</select></label>`;}
