 setPage('Preguntas',`${btn('← Volver al curso','course',`data-id="${courseId}"`,'outline')}${pageHeader(esc(quiz.title),'Prepara las preguntas antes de publicar la evaluación.',btn('+ Nueva pregunta','question-form',`data-quiz="${quizId}" data-course="${courseId}"`,'primary'))}<div class="card spaced"><div class="pill-row"><span class="tag">${quiz.kind==='exam'?'Examen':'Práctica'}</span><span class="tag ${quiz.published?'success':'warn'}">${quiz.published?'Publicado':'Borrador'}</span><span class="tag">${quiz.max_attempts} intentos</span></div><p class="mini-note">Las respuestas correctas solo se devuelven a un estudiante después de entregar el examen; este editor es exclusivo para el propietario del curso.</p></div><div class="list">${quiz.questions.length?quiz.questions.map((q,i)=>`<div class="card"><div class="bar-row"><h3>${i+1}. ${esc(q.prompt)}</h3><div class="actions">${btn('Editar','question-form',`data-question="${q.id}" data-quiz="${quizId}" data-course="${courseId}"`,'outline')}${btn('Eliminar','delete-question',`data-question="${q.id}" data-quiz="${quizId}" data-course="${courseId}"`,'danger')}</div></div><ol type="A">${q.options.map((o,j)=>`<li style="margin:7px 0">${esc(o)} ${j===q.answer_index?'<span class="tag success">Correcta</span>':''}</li>`).join('')}</ol><p class="hint">${esc(q.explanation)}</p></div>`).join(''):empty('No hay preguntas','Crea al menos una pregunta antes de comenzar.')}</div>`);
